script:
// ---------- 1) BEÁLLÍTÁS / SETUP ----------
stage(1000, 600, "#000000");
title({hu: "Vitorlás a nyílt tengeren – filmes jelenet", en: "Sailing ship at sea – cinematic scene"}, {color: "#f1dcc0"});
plotWindow(60);                                       // a grafikonok a teljes 60 s-os filmet mutatják / the graphs show the whole 60 s film

choice("shot", {hu: "Jelenet", en: "Shot"}, [
  ["auto", {hu: "Automatikus – a teljes film", en: "Automatic – the whole film"}],
  ["0", {hu: "1 – Drónfelvétel a hajó fölött", en: "1 – Drone shot above the ship"}],
  ["1", {hu: "2 – Alacsony követő felvétel", en: "2 – Low tracking shot"}],
  ["2", {hu: "3 – Körbeforgó daru", en: "3 – Orbiting crane"}],
  ["3", {hu: "4 – Kamera a hajó orrában", en: "4 – Camera on the bow"}],
  ["4", {hu: "5 – A nagy távolodás", en: "5 – The great pull-back"}]], "auto");
param("shk", {hu: "Kamerarázkódás", en: "Camera shake"}, 0, 2, 1, 0.1, "×");
param("lens", {hu: "Objektív (nagyítás)", en: "Lens zoom"}, 0.7, 1.4, 1, 0.05, "×");
param("qual", {hu: "Tenger részletessége", en: "Sea detail"}, 0.5, 1.5, 1, 0.1, "×");
toggle("bars", {hu: "Mozifilm-sávok (2,39:1)", en: "Cinemascope bars (2.39:1)"}, true);
toggle("flare", {hu: "Lencsevisszfény a nap körül", en: "Sun lens flare"}, true);
toggle("titles", {hu: "Címkártya és kifakulás", en: "Title card and fades"}, true);
button({hu: "Újrajátszás", en: "Replay"}, reset);

let tc = 0;                                           // filmidő (s): az egyetlen állapotváltozó / film time (s): the only state variable
update(dt => { tc += dt; });

// ---------- állandók / constants ----------
const SPD = 6;                                        // a hajó sebessége (m/s) ≈ 11,7 csomó, iránya −z / ship speed (m/s) ≈ 11.7 knots, heading −z
const CEN = [0, -250];                                // a hegykoszorú középpontja (x, z) (m) / centre (x, z) of the ring of mountains (m)
const SUN = norm3([0.09, 0.105, -1]);                 // egységvektor az alacsonyan álló nap felé (kb. 6°-kal a horizont fölött, egyenesen előre) / unit vector towards the low sun (about 6° up, straight ahead)
const FILL = norm3([-0.55, 0.45, 0.7]);               // gyenge, hideg égboltfény hátulról-balról / weak cool sky light from behind-left
const HF = [232, 162, 124];                           // a pára színe a horizonton (r, g, b) / haze colour at the horizon (r, g, b)
const SHOT_T0 = [0, 11, 22, 33, 44];                  // az egyes jelenetek kezdőideje (s) / start time of every shot (s)
const SHOT_LEN = [11, 11, 11, 11, 16];                // az egyes jelenetek hossza (s) / length of every shot (s)
const SHOT_NAME = [
  {hu: "Drón a hajó fölött", en: "Drone above the ship"},
  {hu: "Alacsony követés", en: "Low tracking shot"},
  {hu: "Körbeforgó daru", en: "Orbiting crane"},
  {hu: "Kamera az orrban", en: "Camera on the bow"},
  {hu: "A nagy távolodás", en: "The great pull-back"}];

// ---------- kis segédfüggvények (függvénydeklarációk, így bárhol használhatók) / small helpers (function declarations, so they can be used anywhere) ----------
function sstep(a, b, x) { const k = clamp((x - a) / (b - a), 0, 1); return k * k * (3 - 2 * k); }   // sima 0→1 átmenet / smooth 0→1 ramp
function hash(i, j) { const s = sin(i * 12.9898 + j * 78.233) * 43758.5453; return s - floor(s); }   // ismételhető véletlenszám 0…1 / repeatable random 0…1
function dot3(a, b) { return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]; }
function add3(a, b) { return [a[0] + b[0], a[1] + b[1], a[2] + b[2]]; }
function sub3(a, b) { return [a[0] - b[0], a[1] - b[1], a[2] - b[2]]; }
function mul3(a, k) { return [a[0] * k, a[1] * k, a[2] * k]; }
function cross3(a, b) { return [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]]; }
function norm3(a) { return mul3(a, 1 / max(sqrt(dot3(a, a)), 1e-12)); }
function mix(a, b, t) { return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t]; }
function rgb(c) { return "rgb(" + floor(clamp(c[0], 0, 255)) + "," + floor(clamp(c[1], 0, 255)) + "," + floor(clamp(c[2], 0, 255)) + ")"; }

// ---------- kamera (minden képkockán a draw állítja be) / camera (set every frame in draw) ----------
let CAM = [0, 5, 0], RV = [1, 0, 0], UV = [0, 1, 0], FV = [0, 0, -1];   // helyzet, jobbra, fel, előre / position, right, up, forward
let YAW = 0, FL = 700;                                // a kamera elfordulása (rad) és fókusztávolsága (px) / camera yaw (rad) and focal length (px)
const NEARP = 0.3;                                    // közeli vágósík (m) / near clipping plane (m)
function toCam(p) { const q = [p[0] - CAM[0], p[1] - CAM[1], p[2] - CAM[2]]; return [dot3(q, RV), dot3(q, UV), dot3(q, FV)]; }
function scr(v) { return [500 + FL * v[0] / v[2], 300 - FL * v[1] / v[2]]; }
function clipPoly(v) {                                // levágja a sokszögnek a közeli vágósík mögötti részét / cut off the part of a polygon behind the near plane
  let behind = 0;
  for (const q of v) if (q[2] < NEARP) behind++;
  if (behind === 0) return v;
  if (behind === v.length) return [];
  const out = [];
  for (let i = 0; i < v.length; i++) {
    const a = v[i], b = v[(i + 1) % v.length], ia = a[2] >= NEARP, ib = b[2] >= NEARP;
    if (ia) out.push(a);
    if (ia !== ib) { const k = (NEARP - a[2]) / (b[2] - a[2]); out.push([a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, NEARP]); }
  }
  return out;
}
// mélység szerint rendezett rajzlista: a nagyobb kulcsú elem messzebb van, és előbb rajzolódik / depth-sorted drawing list: items with a larger key are farther away and are drawn first
function emitPoly(list, pw, col, alpha, bias) {
  const v = clipPoly(pw.map(toCam));
  if (v.length < 3) return;
  const sp = v.map(q => scr(q));
  let cz = 0, x0 = 1e9, x1 = -1e9, y0 = 1e9, y1 = -1e9;
  for (let i = 0; i < v.length; i++) {
    cz += v[i][2];
    x0 = min(x0, sp[i][0]); x1 = max(x1, sp[i][0]); y0 = min(y0, sp[i][1]); y1 = max(y1, sp[i][1]);
  }
  if (x1 < -30 || x0 > 1030 || y1 < -30 || y0 > 630) return;      // képen kívül / off-screen
  list.push({t: 0, pts: sp, key: cz / v.length - (bias || 0), col, al: alpha});
}
function emitLine(list, a, b, col, lw, alpha) {
  let va = toCam(a), vb = toCam(b);
  if (va[2] < NEARP && vb[2] < NEARP) return;
  if (va[2] < NEARP) { const k = (NEARP - va[2]) / (vb[2] - va[2]); va = [va[0] + (vb[0] - va[0]) * k, va[1] + (vb[1] - va[1]) * k, NEARP]; }
  else if (vb[2] < NEARP) { const k = (NEARP - vb[2]) / (va[2] - vb[2]); vb = [vb[0] + (va[0] - vb[0]) * k, vb[1] + (va[1] - vb[1]) * k, NEARP]; }
  list.push({t: 1, a: scr(va), b: scr(vb), key: (va[2] + vb[2]) / 2, col, lw, al: alpha});
}
function flush(list) {                                // festő-algoritmus: távolról közelre / painter's algorithm: far to near
  list.sort((p, q) => q.key - p.key);
  for (const it of list) {
    if (it.t === 0) {
      const s = rgb(it.col);
      polygon(it.pts, {fill: s, stroke: it.al > 0.98 ? s : null, lw: 1, alpha: it.al});   // az azonos színű körvonal eltakarja a hajszálvékony réseket / same-colour outline hides hairline gaps
    } else line(it.a[0], it.a[1], it.b[0], it.b[1], {stroke: rgb(it.col), lw: it.lw, alpha: it.al});
  }
}

// ---------- égbolt / sky ----------
const SK_H = [255, 170, 112], SK_M = [112, 98, 150], SK_Z = [24, 46, 112];   // a horizont, a közép és a zenit színe / horizon, middle, zenith colour
function skyCol(e) {                                  // az ég színe e magasságban (rad a horizont fölött) / sky colour at elevation e (rad above the horizon)
  const s = pow(clamp(e / 1.1, 0, 1), 0.5);
  return s < 0.5 ? mix(SK_H, SK_M, s * 2) : mix(SK_M, SK_Z, (s - 0.5) * 2);
}

// ---------- hullámok: 5 haladó szinusz összege; a lejtést (WGX, WGZ) is megadja / waves: sum of 5 travelling sines; also gives the slope (WGX, WGZ) ----------
// minden tag: [amplitúdó m, kx 1/m, kz 1/m, körfrekvencia rad/s, fázis] / each term: [amplitude m, kx 1/m, kz 1/m, angular frequency rad/s, phase]
const WV = [[1.3, 0.031, 0.020, 0.55, 0], [0.7, 0.11, 0.07, 0.9, 0.5], [0.45, -0.05, 0.17, 1.2, 1.3],
            [0.22, 0.31, 0.23, 1.7, 2.1], [0.10, 0.53, -0.41, 2.3, 0.7]];
let WGX = 0, WGZ = 0;
function waveH(x, z) {
  let h = 0, gx = 0, gz = 0;
  for (const w of WV) {
    const a = w[1] * x + w[2] * z - w[3] * tc + w[4];
    h += w[0] * sin(a);
    const c = w[0] * cos(a);
    gx += c * w[1]; gz += c * w[2];                   // lejtés: a szinusz deriváltja / slope: derivative of the sine
  }
  WGX = gx; WGZ = gz;
  return h;
}

// ---------- hegyek: lapokból álló csúcsok, egyszer felépítve / mountains: faceted peaks, built once ----------
const MT = [];                                        // lapok: {p: sarokpontok, n: kifelé mutató normális, cen: középpont, sc: megvilágított szín} / faces: {p: corner points, n: outward normal, cen: centre, sc: lit colour}
function mtShade(c, n) {                              // meleg napfény + hideg derítőfény + szórt fény / warm sun + cool fill + ambient
  const ds = max(0, dot3(n, SUN)), df = max(0, dot3(n, FILL)), up = max(0, n[1]);
  return [c[0] * (0.20 + 1.4 * ds + 0.22 * df + 0.10 * up), c[1] * (0.21 + 1.05 * ds + 0.26 * df + 0.11 * up),
          c[2] * (0.30 + 0.65 * ds + 0.42 * df + 0.18 * up)];
}
function addMountain(cx, cz, H, R, sd) {              // csúcs (cx, cz)-ben, H magasság, R alapsugár / peak at (cx, cz), height H, base radius R
  const N = 9, rot0 = 6.283 * hash(sd, 3);
  const ex = 0.8 + 0.6 * hash(sd, 1), ez = 0.8 + 0.6 * hash(sd, 2);     // gerinccé nyújtva / stretched into a ridge
  const LV = [[1, 0], [0.62, 0.30], [0.36, 0.62], [0.14, 0.88]];          // a 4 gyűrű [sugártényező, magasságtényező] értéke / [radius factor, height factor] of the 4 rings
  const V = [];
  for (let j = 0; j < 4; j++) {
    const row = [];
    for (let k = 0; k < N; k++) {
      const a = rot0 + 2 * PI * k / N;
      const rr = R * LV[j][0] * (0.72 + 0.56 * hash(sd * 7 + j, k + 3));                     // egyenetlen körvonal / rough outline
      const yy = H * LV[j][1] * (j === 0 ? 1 : 0.9 + 0.2 * hash(sd * 5 + j, k + 11));
      row.push([cx + rr * cos(a) * ex, yy, cz + rr * sin(a) * ez]);
    }
    V.push(row);
  }
  const apex = [cx + R * 0.03 * (hash(sd, 8) - 0.5), H, cz];
  const base = [cx, H * 0.3, cz];
  const pushFace = pts => {
    const cen = [0, 0, 0];
    for (const p of pts) { cen[0] += p[0]; cen[1] += p[1]; cen[2] += p[2]; }
    cen[0] /= pts.length; cen[1] /= pts.length; cen[2] /= pts.length;
    let n = pts.length === 3 ? cross3(sub3(pts[1], pts[0]), sub3(pts[2], pts[0])) : cross3(sub3(pts[2], pts[0]), sub3(pts[3], pts[1]));
    n = norm3(n);
    if (dot3(n, sub3(cen, base)) < 0) n = mul3(n, -1);                 // a normális kifelé mutasson / make the normal point outwards
    const ym = cen[1] / H, nz = hash(sd * 3 + floor(cen[0] / 50), floor(cen[2] / 50) + 5);
    let c;
    if (ym > 0.56 + 0.12 * nz) c = [238, 238, 248];                                   // hó / snow
    else if (ym > 0.26) c = [104 + 22 * nz, 94 + 18 * nz, 98 + 16 * nz];             // csupasz szikla / bare rock
    else c = [44 + 14 * nz, 60 + 18 * nz, 52 + 12 * nz];                              // sötét fenyőerdő / dark pine forest
    MT.push({p: pts, n, cen, sc: mtShade(c, n)});
  };
  for (let j = 0; j < 3; j++) for (let k = 0; k < N; k++) pushFace([V[j][k], V[j][(k + 1) % N], V[j + 1][(k + 1) % N], V[j + 1][k]]);
  for (let k = 0; k < N; k++) pushFace([V[3][k], V[3][(k + 1) % N], apex]);
}
function peakRing(n, r0, r1, h0, h1, k0, sdBase) {    // n csúcs a középpont körül; az egyenesen előre eső szektor (a nap) szabadon marad / n peaks round the centre; the sector straight ahead (the sun) stays open
  for (let i = 0; i < n; i++) {
    const al = wrap(2 * PI * i / n + k0 + 0.25 * (hash(i, sdBase) - 0.5));   // szög a −z tengelytől a +x felé / angle from the −z axis, towards +x
    if (al > -0.30 && al < 0.42) continue;
    const rho = lerp(r0, r1, hash(i + 40, sdBase)), H = lerp(h0, h1, hash(i + 70, sdBase));
    addMountain(CEN[0] + rho * sin(al), CEN[1] - rho * cos(al), H, H * (1.35 + 0.5 * hash(i + 9, sdBase)), sdBase * 31 + i);
  }
}
peakRing(14, 1250, 1700, 170, 340, 0.1, 1);          // belső gyűrű: alacsonyabb dombok / inner ring: lower hills
peakRing(20, 2000, 2700, 380, 740, 0.0, 2);          // külső gyűrű: magas, havas óriások / outer ring: tall snowy giants

// ---------- felhők (mindig a kamera felé néző lapok) / clouds (billboards) ----------
const CL = [];
for (let i = 0; i < 18; i++) {
  const al = 2 * PI * hash(i, 77), rho = lerp(1400, 3200, hash(i, 78));
  CL.push({x: CEN[0] + rho * sin(al), z: CEN[1] - rho * cos(al), y: lerp(220, 520, hash(i, 79)), s: lerp(260, 620, hash(i, 80)), sd: i});
}

// ---------- a hajó / the ship ----------
// Helyi koordináták: x jobb oldal (jobbra), y fel, z a tat felé; az orr z = −24, a tat z = +24. / Local coordinates: x starboard (right), y up, z towards the stern; the bow is at z = −24, the stern at z = +24.
let SHX = 0, SHY = 0, SHZ = 0, PA = 0, RB = 0;       // a hajó helyzete, bólintása (orr fel +) és dőlése (jobb oldal fel +) / ship position, pitch (bow up +) and roll (starboard up +)
function rotL(v) {                                    // helyi irány → világirány (dőlés, aztán bólintás) / local direction → world direction (roll, then pitch)
  const cb = cos(RB), sb = sin(RB), ca = cos(PA), sa = sin(PA);
  const x1 = v[0] * cb - v[1] * sb, y1 = v[0] * sb + v[1] * cb;
  return [x1, y1 * ca - v[2] * sa, v[2] * ca + y1 * sa];
}
function xf(p) { const r = rotL(p); return [SHX + r[0], SHY + r[1], SHZ + r[2]]; }

function hullW(u) { return 5.4 * (1 - pow(u, 2.4)); }                // fél hajószélesség az u keresztmetszetnél (0 = tat, 1 = orr) / half beam at station u (0 = stern, 1 = bow)
function hullTop(u) { return 3.4 + 2.4 * pow(u, 2.5) + 1.9 * pow(clamp(1 - u / 0.32, 0, 1), 1.5); }   // a korlát magassága: emelkedő orr, magas tat / rail height: rising bow, high stern

const TPL = [];                                       // álló lapok: {p, c, ref (kifelé mutató irány), em (saját fény), bias} vagy vonalak {ln, p, c, lw, al} / static faces: {p, c, ref (outward direction), em (self-lit), bias} or lines {ln, p, c, lw, al}
const NSTA = 10, ST = [];
for (let i = 0; i < NSTA; i++) {
  const u = i / (NSTA - 1);
  ST.push({u, w: hullW(u), yr: hullTop(u), zl: 24 - 48 * u});
}
function secPts(s, sg) {                              // egy hajótest-keresztmetszet egyik oldala: korlát, aranycsík, domborulat, vízvonal, gerinc / one side of a hull cross-section: rail, gold stripe, bulge, waterline, keel
  return [[sg * 0.88 * s.w, s.yr, s.zl], [sg * 0.93 * s.w, s.yr - 0.55, s.zl], [sg * s.w, 1.6, s.zl],
          [sg * 0.93 * s.w, 0, s.zl], [sg * 0.30 * s.w, -1.9, s.zl]];
}
const HC = [[196, 154, 62], [108, 52, 34], [74, 40, 30], [30, 24, 24]];   // aranycsík, felső hajótest, alsó hajótest, víz alatt / gold stripe, upper hull, lower hull, under water
for (let i = 0; i < NSTA - 1; i++) {
  for (const sg of [-1, 1]) {
    const A = secPts(ST[i], sg), B = secPts(ST[i + 1], sg);
    for (let j = 0; j < 4; j++)
      TPL.push({p: [A[j], B[j], B[j + 1], A[j + 1]], c: HC[j].map(v => v * (0.9 + 0.2 * hash(i * 3 + j, sg + 5))),
                ref: j < 3 ? [sg, 0, 0] : [sg * 0.5, -1, 0]});
    const a1 = [sg * 0.84 * ST[i].w, ST[i].yr - 1.0, ST[i].zl], b1 = [sg * 0.84 * ST[i + 1].w, ST[i + 1].yr - 1.0, ST[i + 1].zl];
    TPL.push({p: [A[0], B[0], b1, a1], c: [92, 56, 36], ref: [-sg, 0, 0]});   // a korlát belső oldala / inner side of the rail
  }
  const dl0 = [-0.84 * ST[i].w, ST[i].yr - 1.0, ST[i].zl], dl1 = [-0.84 * ST[i + 1].w, ST[i + 1].yr - 1.0, ST[i + 1].zl];
  const dr0 = [0.84 * ST[i].w, ST[i].yr - 1.0, ST[i].zl], dr1 = [0.84 * ST[i + 1].w, ST[i + 1].yr - 1.0, ST[i + 1].zl];
  TPL.push({p: [dl0, dl1, dr1, dr0], c: i % 2 ? [150, 112, 70] : [138, 102, 64], ref: [0, 1, 0]});   // fedélzeti deszkák / deck planks
}
{
  const L0 = secPts(ST[0], -1), R0 = secPts(ST[0], 1);
  TPL.push({p: L0.concat(R0.slice().reverse()), c: [86, 44, 30], ref: [0, 0, 1]});    // tattükör / stern transom
  for (const xc of [-3.0, 0, 3.0])                                                      // három kivilágított tatablak / three lit stern windows
    TPL.push({p: [[xc - 0.6, 3.0, 24.05], [xc + 0.6, 3.0, 24.05], [xc + 0.6, 4.2, 24.05], [xc - 0.6, 4.2, 24.05]],
              c: [255, 196, 100], ref: [0, 0, 1], em: true, bias: 4});
}
function boxL(cx, cy, cz, sx, sy, sz, col) {          // egy doboz helyi koordinátákban (6 lap kifelé mutató iránnyal) / a box in local coordinates (6 faces with outward directions)
  const x0 = cx - sx / 2, x1 = cx + sx / 2, y0 = cy - sy / 2, y1 = cy + sy / 2, z0 = cz - sz / 2, z1 = cz + sz / 2;
  const Q = [[[x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1], [0, 0, 1]],
             [[x1, y0, z0], [x0, y0, z0], [x0, y1, z0], [x1, y1, z0], [0, 0, -1]],
             [[x0, y0, z0], [x0, y0, z1], [x0, y1, z1], [x0, y1, z0], [-1, 0, 0]],
             [[x1, y0, z1], [x1, y0, z0], [x1, y1, z0], [x1, y1, z1], [1, 0, 0]],
             [[x0, y1, z1], [x1, y1, z1], [x1, y1, z0], [x0, y1, z0], [0, 1, 0]],
             [[x0, y0, z0], [x1, y0, z0], [x1, y0, z1], [x0, y0, z1], [0, -1, 0]]];
  for (const q of Q) TPL.push({p: q.slice(0, 4), c: col, ref: q[4]});
}
const MZ = [11, -1, -13], MTOP = [30, 38, 33];        // hátsó, fő- és elülső árboc: z helyzet és csúcsmagasság (m) / mizzen, main and fore mast: z position and top height (m)
const SAILS = [];
for (let m = 0; m < 3; m++) {
  boxL(0, (2 + MTOP[m]) / 2, MZ[m], 0.8, MTOP[m] - 2, 0.8, [92, 66, 44]);   // az árboc / the mast
  const L = (MTOP[m] - 2 - 5.5) / 3;                  // egy vitorlarész magassága / height of one sail section
  for (let k = 0; k < 3; k++) {
    const s = {zm: MZ[m], y0: 5.5 + k * L, y1: 5.5 + k * L + L - 0.9, hw: [7.8, 6.4, 4.8][k], seed: m * 3 + k};
    SAILS.push(s);
    boxL(0, s.y1 + 0.12, s.zm - 0.3, 2 * s.hw + 1.2, 0.3, 0.3, [70, 50, 34]);   // vitorlarúd / yard arm
