function shade(c, n) {                                // hajótest- és árboclapok: meleg nap, hideg derítőfény, sötét szórt fény / hull and mast faces: warm sun, cool fill, dark ambient
  const ds = max(0, dot3(n, SUN)), df = max(0, dot3(n, FILL));
