function drawMountains() {
  const vis = [];
  for (const f of MT) {
    const dx = f.cen[0] - CAM[0], dy = f.cen[1] - CAM[1], dz = f.cen[2] - CAM[2];
    if (f.n[0] * dx + f.n[1] * dy + f.n[2] * dz >= 0) continue;        // a lap a kamerától elfelé néz / face points away from the camera
    const zc = dx * FV[0] + dy * FV[1] + dz * FV[2];
    if (zc < 50) continue;
    const v = f.p.map(toCam);
    let ok = true;
    for (const q of v) if (q[2] < 1) ok = false;
