  } else if (si === 1) {                              // 2: alacsonyan haladó kísérőcsónak, jobb oldalt megelőzi a hajót / 2: low chase boat overtaking along the starboard side
    eye = [shx + lerp(75, 88, ee), 4, shz + lerp(75, -6, ee)];
    tgt = [shx, 15, shz + lerp(2, -6, ee)];
    fl = lerp(950, 820, ee);
