    eye = [shx + lerp(6, 30, ee), lerp(9, 70, pow(ee, 1.25)), shz + lerp(55, 420, ee)];
    tgt = [shx, lerp(18, 25, ee), shz + lerp(-40, -100, ee)];
    fl = lerp(600, 650, ee);
  }
  if (si !== 3) eye[1] = max(eye[1], waveH(eye[0], eye[2]) + 1.7);       // a kamera maradjon a hullámok fölött / keep the camera above the waves

  // kézi kamera rázkódása: a kísérőfelvételen több, a darun alig / handheld shake: more on the low chase shot, almost none on the crane
  const amp = [0.35, 1.3, 0.5, 0.9, 0.25][si] * P.shk;
  const f0 = norm3(sub3(tgt, eye));
  YAW = atan2(f0[0], -f0[2]) + amp * (0.0022 * sin(1.1 * tc) + 0.0012 * sin(2.9 * tc + 1));
  const pitch = asin(clamp(f0[1], -1, 1)) + amp * (0.0020 * sin(0.9 * tc + 2) + 0.0010 * sin(3.3 * tc));
  CAM = [eye[0] + amp * 0.12 * sin(1.7 * tc), eye[1] + amp * 0.10 * sin(2.1 * tc + 0.5), eye[2] + amp * 0.12 * sin(1.3 * tc + 2)];
  FL = fl * P.lens;
  RV = [cos(YAW), 0, sin(YAW)];
  FV = [sin(YAW) * cos(pitch), sin(pitch), -cos(YAW) * cos(pitch)];
  UV = [-sin(YAW) * sin(pitch), cos(pitch), cos(YAW) * sin(pitch)];
  const yh = 300 + FL * tan(pitch);                   // a horizont y koordinátája a képen / screen y of the horizon

  // ----- a világ kirajzolása távolról közelre / render the world, far to near -----
  drawSky(yh);
  const sunPos = drawSun();
  drawClouds();
  if (yh < 600) drawSea(yh);
  drawMountains();
  flush(buildWake());                                 // a hab a vízen fekszik, a hajótest alatt / foam lies on the water, below the hull
  const L = [];
  for (const f of TPL) emitShip(L, f);
  for (const f of buildSails()) emitShip(L, f);
  emitBirds(L);
  flush(L);

  // ----- filmes hatás / film look -----
  if (P.flare && sunPos && sunPos[0] > -200 && sunPos[0] < 1200) {      // anamorf fénycsík és szellemképek a lencsében / anamorphic streak and ghost reflections in the lens
    const sx = sunPos[0], sy = sunPos[1], s = sunPos[2];
    ellipse(sx, sy, 420 * s, 3.5 * s, {fill: "#9ec8ff", stroke: null, alpha: 0.22});
    ellipse(sx, sy, 160 * s, 2 * s, {fill: "#ffffff", stroke: null, alpha: 0.5});
    const GH = [[0.45, 18, "#6fa8ff"], [0.8, 30, "#ffb070"], [1.35, 14, "#9affc0"], [1.7, 40, "#ff7090"]];
    for (const g of GH) circle(sx + (500 - sx) * g[0], sy + (300 - sy) * g[0], g[1] * s, {fill: g[2], stroke: null, alpha: 0.12});
  }
  const glare = clamp((dot3(FV, SUN) - 0.8) / 0.2, 0, 1);               // ragyogás, ha a kamera a napba néz / bloom when looking into the sun
  if (glare > 0.01) rect(0, 0, 1000, 600, {fill: "#ffb060", stroke: null, alpha: 0.16 * glare});
  rect(0, 0, 1000, 300, {fill: "#ff9a3c", stroke: null, alpha: 0.05});   // színkorrekció: meleg felül, kékeszöld alul / colour grade: warm top, teal bottom
  rect(0, 300, 1000, 300, {fill: "#0a3c5a", stroke: null, alpha: 0.08});
  for (let k = 0; k < 7; k++) ring(500, 300, 340 + k * 55, 520 + k * 55, {fill: "#000", stroke: null, alpha: 0.16});   // vignetta / vignette
  for (let k = 0; k < 40; k++) rect(random() * 1000, random() * 600, 2, 2, {fill: "#fff", stroke: null, alpha: 0.05});   // filmszemcse / film grain
  if (P.bars) { rect(0, 0, 1000, 91, {fill: "#000", stroke: null}); rect(0, 509, 1000, 91, {fill: "#000", stroke: null}); }

  // ----- címkártya és elsötétítés (csak a teljes filmnél) / title card and fades (full film only) -----
  const auto = P.shot === "auto";
  const blk = P.titles ? max(1 - sstep(0, 1.8, tc), auto ? sstep(57.2, 59.5, tc) : 0) : 0;
  if (blk > 0.002) rect(0, 0, 1000, 600, {fill: "#000", stroke: null, alpha: blk});
  if (auto && P.titles) {
    const ta = sstep(2.6, 3.8, tc) * (1 - sstep(6.4, 7.6, tc));
    if (ta > 0.002) {
      text({hu: "A VÉGTELEN HORIZONT", en: "BEYOND THE HORIZON"}, 500, 190, {size: 44, bold: true, color: "#f6e6cf", align: "center", alpha: ta});
      text({hu: "Egy vitorlás útja", en: "A voyage under sail"}, 500, 228, {size: 20, italic: true, color: "#e3c9a5", align: "center", alpha: ta});
    }
  }

  // ----- mért értékek és grafikonok / readouts and graphs -----
  show({hu: "Jelenet", en: "Shot"}, tr(SHOT_NAME[si]), "", 0);
  show({hu: "Film ideje", en: "Film time"}, tc, "s", 1);
  show({hu: "Hajó sebessége", en: "Ship speed"}, SPD * 1.944, "csomó / knots", 1);
  show({hu: "Hullámmagasság a hajónál", en: "Wave height at the ship"}, hM, "m", 2);
  show({hu: "Kamera magassága", en: "Camera altitude"}, CAM[1], "m", 1);
  plot({hu: "Hullámmagasság a hajónál", en: "Wave height at the ship"}, hM, {unit: "m", color: C.teal});
  plot({hu: "Kamera magassága", en: "Camera altitude"}, CAM[1], {unit: "m", color: C.orange, min: 0});
});
